pred_sql:
SELECT School, MailZip
FROM schools
WHERE AdmFName1 = 'Avetik' AND AdmLName1 = 'Atoian';

SELECT StatusType, COUNT(*) 
FROM schools 
WHERE County = 'Alpine' AND (StatusType = 'Active' OR StatusType = 'Closed') AND `School Type` = 'District Community Day Schools';

SELECT layout 
FROM cards 
WHERE keywords LIKE '%Flying%';

SELECT COUNT(*)
FROM sets
WHERE mtgoCode IS NULL OR mtgoCode = '';

SELECT Age 
FROM users 
WHERE Location = 'Vienna, Austria';

SELECT COUNT(*) 
FROM Player 
WHERE player_name LIKE 'Aaron%' AND birthday > '1990';

SELECT COUNT(DISTINCT account_id)
FROM loan
WHERE status IN ('C', 'D');

SELECT COUNT(DISTINCT driverId) 
FROM results 
WHERE raceId = (SELECT raceId FROM races WHERE date = '2015-11-29') AND time IS NOT NULL;

SELECT SUM(wins) AS total_victories
FROM driverStandings
WHERE points = 91;

SELECT CAST(SUM(CASE WHEN UA <= 6.5 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) 
FROM Laboratory 
WHERE `U-PRO` > 0 AND `U-PRO` < 30;

SELECT ID
FROM Examination
WHERE Thrombosis = 0 AND CPK < 250;

SELECT CAST(SUM(CASE WHEN element = 'h' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(atom_id) AS percent
FROM atom
WHERE molecule_id = 'TR206';

SELECT DISTINCT element
FROM atom
WHERE molecule_id = 'TR004';
